import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.DToEn73J.js";const p=JSON.parse('{"title":"架构决策矩阵","description":"","frontmatter":{"title":"架构决策矩阵","chapter":"附录","order":2,"summary":"全站关键选型对照速查页，索引式汇总 + 跳转链接，不复述各页正文。"},"headers":[],"relativePath":"decision-matrix.md","filePath":"decision-matrix.md","lastUpdated":1788255095000}'),n={name:"decision-matrix.md"};function h(i,t,l,o,s,c){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="架构决策矩阵" tabindex="-1">架构决策矩阵 <a class="header-anchor" href="#架构决策矩阵" aria-label="Permalink to &quot;架构决策矩阵&quot;">​</a></h1><blockquote><p>读完全站后的速查页：把反复出现的选型决策集中成对照表，每条附跳转链接。本文不重复各页正文，只做索引式汇总。</p></blockquote><h2 id="_1-推理范式-react-vs-plan-and-execute" tabindex="-1">1. 推理范式：ReAct vs Plan-and-Execute <a class="header-anchor" href="#_1-推理范式-react-vs-plan-and-execute" aria-label="Permalink to &quot;1. 推理范式：ReAct vs Plan-and-Execute&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>ReAct（走一步看一步）</th><th>Plan-and-Execute（先规划后执行）</th></tr></thead><tbody><tr><td>适用任务</td><td>探索性强、步骤依赖运行时反馈</td><td>步骤可预判、规模大、需可控性</td></tr><tr><td>可控性</td><td>低，易跑偏</td><td>高，计划可审阅</td></tr><tr><td>重规划</td><td>每步自然修正</td><td>需显式触发重规划</td></tr><tr><td>成本</td><td>单步便宜但可能绕路</td><td>规划有额外开销但总步数更稳</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/04-planning-execution/plan-and-execute">4.1 Plan-and-Execute 模式切换</a>；混合模式见 <a href="/fk-ai-agent/01-agent-basics/agent-loop">1.1 Agent Loop</a>。</p><h2 id="_2-能力扩展-mcp-vs-自建-skill" tabindex="-1">2. 能力扩展：MCP vs 自建 Skill <a class="header-anchor" href="#_2-能力扩展-mcp-vs-自建-skill" aria-label="Permalink to &quot;2. 能力扩展：MCP vs 自建 Skill&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>MCP（协议化远程能力）</th><th>自建 Skill（本地能力包）</th></tr></thead><tbody><tr><td>通信</td><td>标准 client-server，跨进程/跨语言</td><td>进程内或脚本，无标准协议</td></tr><tr><td>复用</td><td>社区/第三方 server 即插即用</td><td>需自行维护</td></tr><tr><td>隔离</td><td>天然进程隔离，便于沙箱</td><td>隔离需额外设计</td></tr><tr><td>成本</td><td>多一次 transport 开销</td><td>零通信开销</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/02-capability-extension/mcp">2.2 MCP 加载与扩展</a>、<a href="/fk-ai-agent/02-capability-extension/skill-management">2.1 Skill 加载与管理</a>。</p><h2 id="_3-长期记忆-本地文件-vs-向量库-vs-mem0" tabindex="-1">3. 长期记忆：本地文件 vs 向量库 vs mem0 <a class="header-anchor" href="#_3-长期记忆-本地文件-vs-向量库-vs-mem0" aria-label="Permalink to &quot;3. 长期记忆：本地文件 vs 向量库 vs mem0&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>本地文件（append-only log / md）</th><th>向量库</th><th>mem0</th></tr></thead><tbody><tr><td>语义检索</td><td>弱（关键词）</td><td>强（dense）</td><td>强 + 自动抽取</td></tr><tr><td>写入复杂度</td><td>极低</td><td>中（embedding 管线）</td><td>中（托管/自托管）</td></tr><tr><td>适合</td><td>审计日志、结构化笔记</td><td>大规模知识检索</td><td>对话级记忆抽取</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/03-context-memory/long-term-memory">3.3 长期记忆管理</a>；检索集成见 <a href="/fk-ai-agent/03-context-memory/rag">3.5 RAG</a>。</p><h2 id="_4-工具并发-有副作用-vs-无副作用" tabindex="-1">4. 工具并发：有副作用 vs 无副作用 <a class="header-anchor" href="#_4-工具并发-有副作用-vs-无副作用" aria-label="Permalink to &quot;4. 工具并发：有副作用 vs 无副作用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>无副作用工具（查询/计算）</th><th>有副作用工具（写文件/发邮件）</th></tr></thead><tbody><tr><td>能否并行</td><td>可以</td><td>谨慎，需顺序或显式同步</td></tr><tr><td>结果对齐</td><td>乱序返回按 call_id 对齐</td><td>需保证顺序与幂等</td></tr><tr><td>风险</td><td>低</td><td>重复执行、状态冲突</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/01-agent-basics/concurrency">1.5 并发与竞态</a>、<a href="/fk-ai-agent/01-agent-basics/tool-abstraction">1.2 工具抽象</a>。</p><h2 id="_5-安全控制-kill-switch-vs-审计回滚" tabindex="-1">5. 安全控制：Kill Switch vs 审计回滚 <a class="header-anchor" href="#_5-安全控制-kill-switch-vs-审计回滚" aria-label="Permalink to &quot;5. 安全控制：Kill Switch vs 审计回滚&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Kill Switch（紧急停止）</th><th>审计回滚（Audit &amp; Rollback）</th></tr></thead><tbody><tr><td>时序</td><td>运行时熔断</td><td>事后纠错</td></tr><tr><td>目标</td><td>立刻止损</td><td>恢复到已知良好状态</td></tr><tr><td>依赖</td><td>全局中断信号/断路器</td><td>结构化 trace + checkpoint</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/05-safety-governance/kill-switch">5.4 紧急停止机制</a>、<a href="/fk-ai-agent/05-safety-governance/audit-rollback">5.2 审计和回滚</a>。</p><h2 id="_6-prompt-版本管理-同仓-vs-独立" tabindex="-1">6. Prompt 版本管理：同仓 vs 独立 <a class="header-anchor" href="#_6-prompt-版本管理-同仓-vs-独立" aria-label="Permalink to &quot;6. Prompt 版本管理：同仓 vs 独立&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>与代码同仓</th><th>独立管理（Prompt 平台）</th></tr></thead><tbody><tr><td>评审</td><td>走代码 PR</td><td>走平台工作流</td></tr><tr><td>A/B 与灰度</td><td>需自建</td><td>平台内置</td></tr><tr><td>门槛</td><td>低</td><td>需额外系统</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/06-engineering-ops/prompt-management">6.1 Prompt 管理</a>。</p><h2 id="_7-模型编排-路由与-fallback" tabindex="-1">7. 模型编排：路由与 fallback <a class="header-anchor" href="#_7-模型编排-路由与-fallback" aria-label="Permalink to &quot;7. 模型编排：路由与 fallback&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>单模型</th><th>多模型路由 + fallback</th></tr></thead><tbody><tr><td>成本</td><td>固定</td><td>简单任务走低廉模型</td></tr><tr><td>质量</td><td>取决于单模型天花板</td><td>复杂任务升级强模型</td></tr><tr><td>复杂度</td><td>低</td><td>需路由策略与链</td></tr></tbody></table><p>→ 详见 <a href="/fk-ai-agent/04-planning-execution/model-routing">4.4 模型路由与多模型编排</a>、<a href="/fk-ai-agent/06-engineering-ops/cost-latency">6.4 成本与延迟优化</a>。</p><hr><p><em>最后核实日期：2026-08-26</em></p>',25)])])}const m=a(n,[["render",h]]);export{p as __pageData,m as default};
